// --- Justified Grid Layout (Google Photos Style) ---

const justifiedPhotos = new Set();
const TARGET_ROW_HEIGHT = 225; // Desired row height
const SPACING = 4;             // Gap between images (px)

/**
 * Justifies a single row of photos to fill container width.
 */
function justifyRow(row, containerWidth) {
    if (!row.length) return;

    let totalScaledWidth = row.reduce((sum, photo) => {
        const ow = +photo.dataset.originalWidth;
        const oh = +photo.dataset.originalHeight;
        return sum + (ow * TARGET_ROW_HEIGHT / oh);
    }, 0);

    const totalSpacing = SPACING * (row.length - 1);

    // If last row has few items, keep target height
    const isLastRow =
        row[row.length - 1] ===
        Array.from(
            document.querySelectorAll('.photo-thumbnail-container:not([data-justified="true"])')
        ).pop();

    const newHeight =
        !isLastRow || row.length >= 3
            ? (containerWidth - totalSpacing) * (TARGET_ROW_HEIGHT / totalScaledWidth)
            : TARGET_ROW_HEIGHT;

    row.forEach(photo => {
        const ow = +photo.dataset.originalWidth;
        const oh = +photo.dataset.originalHeight;
        const newWidth = ow * (newHeight / oh);

        photo.style.width = `${newWidth}px`;
        photo.style.height = `${newHeight}px`;
        photo.style.marginRight = `${SPACING / 2}px`;
        photo.style.marginLeft = `${SPACING / 2}px`;
        photo.style.marginBottom = `${SPACING}px`;

        photo.dataset.justified = "true";
        justifiedPhotos.add(photo);
    });
}

/**
 * Lays out all new photos that haven’t been justified yet.
 */
window.justifyNewPhotos = function() {
    let gallery = document.getElementById('scroll-gallery');
    if (!gallery) {
        gallery = document.getElementById('infinite-scroll-gallery');
        if (!gallery) {
            return;
        }
    }

    const containerWidth = gallery.clientWidth;
    const photos = Array.from(
        gallery.querySelectorAll('.photo-thumbnail-container:not([data-justified="true"])')
    );
    if (!photos.length) return;

    // Cache original dimensions
    photos.forEach(p => {
        if (!p.dataset.originalWidth || !p.dataset.originalHeight) {
            const widthMatch = p.getAttribute('style')?.match(/width\s*:\s*(\d+)/);
            const heightMatch = p.getAttribute('style')?.match(/height\s*:\s*(\d+)/);
            const w = widthMatch ? parseFloat(widthMatch[1]) : 300;
            const h = heightMatch ? parseFloat(heightMatch[1]) : 225;
            p.dataset.originalWidth = w;
            p.dataset.originalHeight = h;
        }
    });

    let row = [];
    let rowWidth = 0;

    photos.forEach((p, i) => {
        const ow = +p.dataset.originalWidth;
        const oh = +p.dataset.originalHeight;
        const scaledWidth = ow * TARGET_ROW_HEIGHT / oh;

        if (rowWidth + scaledWidth + SPACING * row.length > containerWidth) {
            justifyRow(row, containerWidth);
            row = [p];
            rowWidth = scaledWidth;
        } else {
            row.push(p);
            rowWidth += scaledWidth;
        }

        if (i === photos.length - 1 && row.length)
            justifyRow(row, containerWidth);
    });
};

/**
 * Recalculates date header positions (for visual grouping)
 */
function positionDateHeaders() {
    let gallery = document.getElementById('scroll-gallery');
    if (!gallery) {
        gallery = document.getElementById('infinite-scroll-gallery');
        if (!gallery) {
            return;
        }
    }

    gallery.querySelectorAll('.dateHeader').forEach(header => {
        header.style.width = `${gallery.clientWidth}px`;
    });
}

// --- Event Hooks ---

window.addEventListener('load', () => {
    window.justifyNewPhotos();
    positionDateHeaders();
});

window.addEventListener('resize', () => {
    document.querySelectorAll('.photo-thumbnail-container').forEach(p => {
        delete p.dataset.justified;
    });
    justifiedPhotos.clear();
    window.justifyNewPhotos();
    positionDateHeaders();
});

// Observe DOM changes (infinite scrolling)
const observer = new MutationObserver(() => {
    window.justifyNewPhotos();
    positionDateHeaders();
});
observer.observe(document.querySelector('#scroll-gallery'), {
    childList: true,
    subtree: true
});
observer.observe(document.querySelector('#infinite-scroll-gallery'), {
    childList: true,
    subtree: true
});
